  const int lane  = tid % BM;       // output-column tile lane
  const int split = tid / BM;       // reduction split id
  // Vectorized global loads: when the contiguous inner extent is divisible
  // by 4, each lane owns float4 chunks so a warp touches consecutive 16B
  // words. Otherwise the kernel uses the original scalar coalesced path.
  constexpr int BT = BM * V;
  const bool use_vec = ((inner & 3) == 0);
  const int tile_cols = use_vec ? (BT * 4) : BT;
  const int tiles = (inner + tile_cols - 1) / tile_cols;
  const int lin   = blockIdx.x;
  const int o     = lin / tiles;
  const int t     = lin - o * tiles;
  const int base  = t * BT + lane;
  const int64_t sOuter = (int64_t)R * inner;
  const int64_t sRed   = (int64_t)inner;
  const int64_t sInner = 1;
  Tensor mX = make_tensor(
      make_gmem_ptr(X),
      make_shape(outer, R, inner),
      make_stride(sOuter, sRed, sInner));
  Tensor mY = make_tensor(
      make_gmem_ptr(Y),
      make_shape(outer, inner),
      make_stride((int64_t)inner, (int64_t)1));
  __shared__ float sm[RS][BT * 4];
  const float inf = __int_as_float(0x7f800000);
  constexpr int UR = 4;
  if (use_vec) {
    const int inner4 = inner >> 2;
    const bool full_tile = (((int64_t)t + 1) * BT) <= inner4;
    float4 acc[V];
    #pragma unroll
    for (int k = 0; k < V; ++k) {
      acc[k] = make_float4(inf, inf, inf, inf);
    }
    if (full_tile) {
      const float* __restrict__ po = X + (int64_t)o * sOuter + (int64_t)base * 4;
      int r = split;
      for (; r + (UR - 1) * RS < R; r += UR * RS) {
        #pragma unroll
        for (int u = 0; u < UR; ++u) {
          const float4* __restrict__ pu =
              reinterpret_cast<const float4*>(po + (int64_t)(r + u * RS) * sRed);
          #pragma unroll
          for (int k = 0; k < V; ++k) {
            const float4 x = __ldcs(pu + k * BM);
            acc[k].x = fminf(acc[k].x, x.x);
            acc[k].y = fminf(acc[k].y, x.y);
            acc[k].z = fminf(acc[k].z, x.z);
            acc[k].w = fminf(acc[k].w, x.w);
          }
        }
      }
      for (; r < R; r += RS) {
        const float4* __restrict__ pr =
            reinterpret_cast<const float4*>(po + (int64_t)r * sRed);
        #pragma unroll
        for (int k = 0; k < V; ++k) {
          const float4 x = __ldcs(pr + k * BM);
          acc[k].x = fminf(acc[k].x, x.x);
          acc[k].y = fminf(acc[k].y, x.y);
          acc[k].z = fminf(acc[k].z, x.z);
          acc[k].w = fminf(acc[k].w, x.w);
        }
      }
    } else {
      for (int r = split; r < R; r += RS) {
        const float4* __restrict__ pr = reinterpret_cast<const float4*>(
            X + (int64_t)o * sOuter + (int64_t)r * sRed);
        #pragma unroll
        for (int k = 0; k < V; ++k) {
          const int c = base + k * BM;
          if (c < inner4) {
            const float4 x = __ldcs(pr + c);
            acc[k].x = fminf(acc[k].x, x.x);
            acc[k].y = fminf(acc[k].y, x.y);
            acc[k].z = fminf(acc[k].z, x.z);
            acc[k].w = fminf(acc[k].w, x.w);
          }
        }
      }
    }
    #pragma unroll
    for (int k = 0; k < V; ++k) {
      const int sc = (k * BM + lane) * 4;
      sm[split][sc + 0] = acc[k].x;
      sm[split][sc + 1] = acc[k].y;
      sm[split][sc + 2] = acc[k].z;
      sm[split][sc + 3] = acc[k].w;
    }
    __syncthreads();
    if (split == 0) {
      #pragma unroll
      for (int k = 0; k < V; ++k) {
        const int c = base + k * BM;
        if (c < inner4) {
          const int sc = (k * BM + lane) * 4;
