        const float* __restrict__ pu = po + (int64_t)(r + u * RS) * sRed;
        #pragma unroll
        for (int k = 0; k < V; ++k) {
          acc[k] = fminf(acc[k], __ldcs(pu + k * BM));
        }
      }
    }
    for (; r < R; r += RS) {
      const float* __restrict__ pr = po + (int64_t)r * sRed;
      #pragma unroll
      for (int k = 0; k < V; ++k) {
        acc[k] = fminf(acc[k], __ldcs(pr + k * BM));
      }
    }
  } else {
    for (int r = split; r < R; r += RS) {
      #pragma unroll
      for (int k = 0; k < V; ++k) {
        const int i = base + k * BM;
        if (i < inner) {
          acc[k] = fminf(acc[k], __ldcs(X + (int64_t)o * sOuter + (int64_t)r * sRed + i));
