  for (int k = 0; k < V; ++k) {
    sm[split][k * BM + lane] = acc[k];
  }
  __syncthreads();
  if (split == 0) {
    #pragma unroll
    for (int k = 0; k < V; ++k) {
      const int i = base + k * BM;
      if (i < inner) {
        float m = sm[0][k * BM + lane];
        #pragma unroll
        for (int s = 1; s < RS; ++s) {
          m = fminf(m, sm[s][k * BM + lane]);
        }
        mY(o, i) = m;
      }
    }
  }
