torch::Tensor min_reduce(torch::Tensor x, int64_t dim) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

  auto xc = x.contiguous();
  const int64_t nd = xc.dim();
  TORCH_CHECK(nd >= 1, "x must have at least one dimension");

  if (dim < 0) dim += nd;
  TORCH_CHECK(dim >= 0 && dim < nd, "dim out of range");

  int64_t outer = 1;
  for (int64_t d = 0; d < dim; ++d) outer *= xc.size(d);
  const int64_t R = xc.size(dim);
  int64_t inner = 1;
  for (int64_t d = dim + 1; d < nd; ++d) inner *= xc.size(d);
  TORCH_CHECK(R > 0, "cannot reduce over an empty dimension");

  auto out_sizes = xc.sizes().vec();
  out_sizes.erase(out_sizes.begin() + dim);
  auto y = torch::empty(out_sizes, xc.options());
  if (y.numel() == 0) return y;

  constexpr int BM = 128;
  constexpr int RS = 4;
  constexpr int V  = 2;
  constexpr int BT = BM * V;
  constexpr int THREADS = BM * RS;
  const bool use_vec = ((inner % 4) == 0);
  const int64_t tile_cols = use_vec ? (int64_t)BT * 4 : (int64_t)BT;
  const int64_t tiles = (inner + tile_cols - 1) / tile_cols;
  const int64_t blocks = outer * tiles;
  TORCH_CHECK(blocks > 0 && blocks < 2147483647LL, "invalid grid size");
  dim3 grid((unsigned)blocks);
  dim3 block(THREADS);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  min_reduce_cute_kernel<BM, RS, V><<<grid, block, 0, stream>>>(
      xc.data_ptr<float>(),
      y.data_ptr<float>(),
      (int)outer, (int)R, (int)inner);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "min_reduce_cute_kernel failed: ",
              cudaGetErrorString(err));
  return y;
}
